inline Stage1 stage1(int market) {
  Stage1 r; r.valid = false; r.from = r.to = -1; r.centre = r.half = r.p = r.pLod = r.show = NAN;
  switch (market) {
    case ES: r.from = es_ch::kS1From; r.to = es_ch::kS1To; r.p = es_ch::kS1P; r.pLod = es_ch::kPLod; r.show = es_ch::kShow1; break;
    case NQ: r.from = nq_ch::kS1From; r.to = nq_ch::kS1To; r.p = nq_ch::kS1P; r.pLod = nq_ch::kPLod; r.show = nq_ch::kShow1; break;
    case CL: r.from = cl_ch::kS1From; r.to = cl_ch::kS1To; r.p = cl_ch::kS1P; r.pLod = cl_ch::kPLod; r.show = cl_ch::kShow1; break;
    case GC: r.from = gc_ch::kS1From; r.to = gc_ch::kS1To; r.p = gc_ch::kS1P; r.pLod = gc_ch::kPLod; r.show = gc_ch::kShow1; break;
    case HG: r.from = hg_ch::kS1From; r.to = hg_ch::kS1To; r.p = hg_ch::kS1P; r.pLod = hg_ch::kPLod; r.show = hg_ch::kShow1; break;
    case NG: r.from = ng_ch::kS1From; r.to = ng_ch::kS1To; r.p = ng_ch::kS1P; r.pLod = ng_ch::kPLod; r.show = ng_ch::kShow1; break;
    case EU: r.from = eu_ch::kS1From; r.to = eu_ch::kS1To; r.p = eu_ch::kS1P; r.pLod = eu_ch::kPLod; r.show = eu_ch::kShow1; break;
    default: return r;
  }
  r.valid = true; r.centre = (r.from + r.to) / 2.0; r.half = (r.to - r.from) / 2.0; return r;
}
template <int KDE, int KUNUSED>
inline Stage2 stage2T(int open, int t1, double depth, int now, double thr, double show, const double (&de)[KDE], const double (&P)[4][KDE][7]) {
  Stage2 r; r.valid = false; r.from = r.to = r.w = -1; r.p = NAN; r.qualified = false; r.show = show;
  if (!std::isfinite(depth) || now < t1) return r;
  int tb = ibinOf(t1 - open, kChT1, 4), db = binOf(depth, de, KDE);
  const double* cur = P[tb][db];
  int el = now - t1; double pe = 0.0;
  for (int k = 0; k < 7; ++k) if (kChW[k] <= el) pe = cur[k];
  r.valid = true; r.from = t1;
  for (int k = 0; k < 7; ++k) {
    if (kChW[k] <= el) continue;
    double c = pe < 1.0 - 1e-12 ? (cur[k] - pe) / (1.0 - pe) : 0.0;
    r.w = kChW[k]; r.p = c; r.to = t1 + r.w;
    if (c >= thr - 1e-12) { r.qualified = true; return r; }
  }
  return r;
}
inline Stage2 stage2(int market, int t1MinuteOfDay, double depthAtr, int nowMinuteOfDay) {
  switch (market) {
    case ES: return stage2T<es_ch::kDE, 0>(kOpen[ES], t1MinuteOfDay, depthAtr, nowMinuteOfDay, es_ch::kThr2, es_ch::kShow2, es_ch::kDepthEdges, es_ch::kP2);
    case NQ: return stage2T<nq_ch::kDE, 0>(kOpen[NQ], t1MinuteOfDay, depthAtr, nowMinuteOfDay, nq_ch::kThr2, nq_ch::kShow2, nq_ch::kDepthEdges, nq_ch::kP2);
    case CL: return stage2T<cl_ch::kDE, 0>(kOpen[CL], t1MinuteOfDay, depthAtr, nowMinuteOfDay, cl_ch::kThr2, cl_ch::kShow2, cl_ch::kDepthEdges, cl_ch::kP2);
    case GC: return stage2T<gc_ch::kDE, 0>(kOpen[GC], t1MinuteOfDay, depthAtr, nowMinuteOfDay, gc_ch::kThr2, gc_ch::kShow2, gc_ch::kDepthEdges, gc_ch::kP2);
    case HG: return stage2T<hg_ch::kDE, 0>(kOpen[HG], t1MinuteOfDay, depthAtr, nowMinuteOfDay, hg_ch::kThr2, hg_ch::kShow2, hg_ch::kDepthEdges, hg_ch::kP2);
    case NG: return stage2T<ng_ch::kDE, 0>(kOpen[NG], t1MinuteOfDay, depthAtr, nowMinuteOfDay, ng_ch::kThr2, ng_ch::kShow2, ng_ch::kDepthEdges, ng_ch::kP2);
    case EU: return stage2T<eu_ch::kDE, 0>(kOpen[EU], t1MinuteOfDay, depthAtr, nowMinuteOfDay, eu_ch::kThr2, eu_ch::kShow2, eu_ch::kDepthEdges, eu_ch::kP2);
  }
  Stage2 r; r.valid = false; r.from = r.to = r.w = -1; r.p = NAN; r.qualified = false; r.show = NAN; return r;
}
template <int KG>
inline Stage3 stage3T(int t1, int tr, int now, double thr, double show, int useSpeed, const int (&G)[KG], const double (&S)[KG][3][KG],
                      const double (&gap)[KG][3]) {
  Stage3 r; r.valid = false; r.afterT = -1; r.afterP = r.gapMin = NAN; r.qualified = false; r.show = show;
  if (tr <= 0 || tr < t1 || now < tr) return r;
  int s = slotOf(tr, G, KG), v = useSpeed ? ibinOf(tr - t1, kChSpeed, 3) : 0;
  r.valid = true; r.gapMin = gap[s][v];
  double den = 1.0;
  if (kStage3CondNow) for (int j = s; j < KG; ++j) if (G[j] <= now) den = S[s][v][j];
  int first = -1;
  for (int j = s; j < KG; ++j) {
    if (G[j] < now) continue;
    double c = den > 1e-12 ? S[s][v][j] / den : 0.0;
    if (first < 0) { first = j; r.afterT = G[j]; r.afterP = c; }
    if (c >= thr - 1e-12) { r.afterT = G[j]; r.afterP = c; r.qualified = true; }
  }
  return r;
}
inline Stage3 stage3(int market, int t1MinuteOfDay, int reclaimMinuteOfDay, int nowMinuteOfDay) {
  switch (market) {
    case ES: return stage3T(t1MinuteOfDay, reclaimMinuteOfDay, nowMinuteOfDay, es_ch::kThr3, es_ch::kShow3, es_ch::kUseSpeed, es_ch::kGrid3, es_ch::kS3, es_ch::kGap3);
    case NQ: return stage3T(t1MinuteOfDay, reclaimMinuteOfDay, nowMinuteOfDay, nq_ch::kThr3, nq_ch::kShow3, nq_ch::kUseSpeed, nq_ch::kGrid3, nq_ch::kS3, nq_ch::kGap3);
    case CL: return stage3T(t1MinuteOfDay, reclaimMinuteOfDay, nowMinuteOfDay, cl_ch::kThr3, cl_ch::kShow3, cl_ch::kUseSpeed, cl_ch::kGrid3, cl_ch::kS3, cl_ch::kGap3);
    case GC: return stage3T(t1MinuteOfDay, reclaimMinuteOfDay, nowMinuteOfDay, gc_ch::kThr3, gc_ch::kShow3, gc_ch::kUseSpeed, gc_ch::kGrid3, gc_ch::kS3, gc_ch::kGap3);
    case HG: return stage3T(t1MinuteOfDay, reclaimMinuteOfDay, nowMinuteOfDay, hg_ch::kThr3, hg_ch::kShow3, hg_ch::kUseSpeed, hg_ch::kGrid3, hg_ch::kS3, hg_ch::kGap3);
    case NG: return stage3T(t1MinuteOfDay, reclaimMinuteOfDay, nowMinuteOfDay, ng_ch::kThr3, ng_ch::kShow3, ng_ch::kUseSpeed, ng_ch::kGrid3, ng_ch::kS3, ng_ch::kGap3);
    case EU: return stage3T(t1MinuteOfDay, reclaimMinuteOfDay, nowMinuteOfDay, eu_ch::kThr3, eu_ch::kShow3, eu_ch::kUseSpeed, eu_ch::kGrid3, eu_ch::kS3, eu_ch::kGap3);
  }
  Stage3 r; r.valid = false; r.afterT = -1; r.afterP = r.gapMin = NAN; r.qualified = false; r.show = NAN; return r;
}
